// O JavaScript roda numa thread só. O event loop decide o que roda a seguir.
setTimeout(() => console.log('E. setTimeout (fila de timers)'), 0);
Promise.resolve().then(() => console.log('C. promise (microtask)'));
process.nextTick(() => console.log('D. process.nextTick'));
console.log('A. síncrono');

// Código síncrono pesado trava TUDO: nenhum timer, request ou job anda
function travar(ms: number): void {
  const fim = Date.now() + ms;
  while (Date.now() < fim) { /* ocupando a thread */ }
}
const antes = Date.now();
setTimeout(() => console.log(`F. timer de 0ms rodou após ${Date.now() - antes}ms`), 0);
travar(300);
console.log('B. síncrono, depois de travar 300ms');

// Saída (Node 24, ESM):
// A. síncrono
// B. síncrono, depois de travar 300ms
// C. promise (microtask)
// D. process.nextTick      ← em ESM vem DEPOIS da promise; em CommonJS, antes
// E. setTimeout (fila de timers)
// F. timer de 0ms rodou após 300ms   ← "0ms" é o mínimo, não uma garantia

import { EventEmitter, on, once } from 'node:events';

interface PedidoEventos {
  criado: [pedido: { id: string; total: number }];
  cancelado: [id: string, motivo: string];
}

const pedidos = new EventEmitter<PedidoEventos>();

pedidos.on('cancelado', (id, motivo) => console.log(`#${id} cancelado: ${motivo}`));
// @ts-expect-error: o evento 'pago' não existe no mapa
pedidos.on('pago', () => {});

// once() devolve uma Promise com os argumentos do PRÓXIMO evento
setTimeout(() => pedidos.emit('criado', { id: 'p1', total: 50 }), 10);
const [pedido] = await once(pedidos, 'criado');
console.log('primeiro pedido:', pedido.id); // 'p1'

// on() transforma eventos em um async iterator
const ac = new AbortController();
setTimeout(() => pedidos.emit('cancelado', 'p2', 'sem estoque'), 10);
setTimeout(() => ac.abort(), 50);
try {
  for await (const [id] of on(pedidos, 'cancelado', { signal: ac.signal })) {
    console.log('via for await:', id); // 'p2'
  }
} catch {
  // abortar o signal encerra o loop com AbortError
}

// Cuidado: emitir 'error' sem nenhum listener lança a exceção e derruba o processo

import { createReadStream, createWriteStream } from 'node:fs';
import { createInterface } from 'node:readline';
import { pipeline } from 'node:stream/promises';
import { createGzip } from 'node:zlib';

// Um log de 5 GB não cabe na memória. Streams processam em pedaços (chunks),
// com uso de memória constante, não importa o tamanho do arquivo.
await pipeline(
  createReadStream('access.log'),
  createGzip(),
  createWriteStream('access.log.gz'),
);
// pipeline cuida dos erros e fecha todos os streams, mesmo se uma etapa falhar

// Ler linha a linha, também em streaming
const linhas = createInterface({ input: createReadStream('access.log'), crlfDelay: Infinity });
let erros = 0;
for await (const linha of linhas) {
  if (linha.endsWith(' 500')) erros++;
}
console.log(`${erros} respostas 500`); // '2 respostas 500'

import { Readable, Transform, Writable } from 'node:stream';
import { pipeline } from 'node:stream/promises';

// Fonte: um async generator vira stream (páginas de uma API, linhas do banco...)
async function* gerarPedidos() {
  for (let i = 1; i <= 3; i++) yield { id: i, total: i * 10 };
}

// Transform em objectMode: recebe objetos, devolve outra coisa
const paraCsv = new Transform({
  objectMode: true,
  transform(pedido: { id: number; total: number }, _encoding, callback) {
    callback(null, `${pedido.id};${pedido.total}\n`);
  },
});

// Destino lento: simula um banco que leva 100ms por escrita
const destinoLento = new Writable({
  highWaterMark: 1, // buffer pequeno para a backpressure aparecer logo
  write(chunk: Buffer, _encoding, callback) {
    process.stdout.write(`gravando ${chunk.toString()}`);
    setTimeout(callback, 100); // só libera o próximo quando chamar callback
  },
});

const inicio = Date.now();
await pipeline(Readable.from(gerarPedidos()), paraCsv, destinoLento);
console.log(`levou ~${Math.round((Date.now() - inicio) / 100) * 100}ms`); // ~300ms: a fonte esperou o destino

// Sem pipeline: write() devolve false quando o buffer enche, e você deveria
// esperar o evento 'drain' antes de escrever de novo. Ignorar isso = memória
// crescendo sem limite. pipeline e for await fazem esse controle por você.

import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';

// Trabalho pesado de CPU (hash, imagem, PDF) trava o event loop.
// worker_threads roda JS em outra thread, com o próprio event loop.
function fibonacci(n: number): number {
  return n < 2 ? n : fibonacci(n - 1) + fibonacci(n - 2);
}

if (isMainThread) {
  const inicio = Date.now();
  const batidas = setInterval(() => console.log(`event loop livre aos ${Date.now() - inicio}ms`), 250);

  // O mesmo arquivo roda como worker, recebendo workerData
  const worker = new Worker(new URL(import.meta.url), { workerData: 38 });
  const resultado = await new Promise<number>((resolve, reject) => {
    worker.once('message', resolve);
    worker.once('error', reject);
  });

  clearInterval(batidas);
  console.log('fibonacci(38) =', resultado);
} else {
  parentPort?.postMessage(fibonacci(workerData as number));
}
// Enquanto a outra thread calcula, as "batidas" continuam: o event loop não travou.
// Em filas, o BullMQ faz isso por job com sandboxed processors (módulo 11).
